<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Register — Public Service Portal</title>
<style>
  :root {
    --navy: #0b1f3a;
    --navy-dark: #071527;
    --orange: #e8701a;
    --orange-dark: #c85e10;
    --bg: #eef2f6;
    --panel: #ffffff;
    --text: #1a2433;
    --muted: #5a6b7f;
    --border: #c9d4e0;
    --error: #b3261e;
    --error-bg: #fdecea;
    --success: #1e6b34;
    --focus: #2e6fb7;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html { -webkit-text-size-adjust: 100%; }
  body {
    font-family: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.5;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
  }
  .service-header {
    background: var(--navy);
    color: #fff;
    width: 100%;
    border-bottom: 4px solid var(--orange);
  }
  .service-header-inner {
    max-width: 1080px;
    margin: 0 auto;
