    display: flex;
    align-items: center;
    gap: 0.9rem;
  }
  .service-mark {
    width: 44px; height: 44px;
    flex: 0 0 auto;
    border-radius: 8px;
    background: var(--orange);
    color: var(--navy-dark);
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 1.25rem;
    letter-spacing: -0.5px;
  }
  .service-header h1 { font-size: 1.3rem; font-weight: 700; letter-spacing: 0.2px; }
  .service-header p { font-size: 0.85rem; color: #b9c8da; margin-top: 0.1rem; }

  main {
    flex: 1;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    padding: 2.5rem 1rem 3rem;
  }
  .panel {
    background: var(--panel);
    width: 100%;
    max-width: 720px;
    border-radius: 10px;
    box-shadow: 0 6px 24px rgba(11, 31, 58, 0.12);
    border: 1px solid #dde5ee;
    padding: 2rem 2rem 2.25rem;
  }
  .panel h2 {
    font-size: 1.45rem;
    color: var(--navy);
    margin-bottom: 0.35rem;
  }
  .panel .intro { color: var(--muted); font-size: 0.95rem; margin-bottom: 1.5rem; }

  .form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.1rem 1.25rem;
  }
  .field { display: flex; flex-direction: column; }
  .field.full { grid-column: 1 / -1; }
  label { font-weight: 600; font-size: 0.92rem; margin-bottom: 0.35rem; color: var(--navy); }
  .optional { font-weight: 400; color: var(--muted); font-size: 0.82rem; margin-left: 0.25rem; }
  .hint { font-size: 0.8rem; color: var(--muted); margin-top: 0.3rem; }

  input[type="text"], input[type="email"], input[type="password"], input[type="date"] {
    width: 100%;
    padding: 0.65rem 0.75rem;
    font-size: 1rem;
    border: 1.5px solid var(--border);
    border-radius: 6px;
    background: #fff;
    color: var(--text);
    transition: border-color 0.15s, box-shadow 0.15s;
  }
  input:focus-visible, button:focus-visible, .checkbox-wrap input:focus-visible + .box {
    outline: 3px solid var(--focus);
    outline-offset: 2px;
  }
  input[aria-invalid="true"] {
    border-color: var(--error);
    background: #fffafa;
  }

  .password-wrap { position: relative; }
  .password-wrap input { padding-right: 4.4rem; }
  .toggle-pw {
    position: absolute;
    right: 0.35rem;
    top: 50%;
    transform: translateY(-50%);
    border: 1px solid var(--border);
    background: #f4f7fb;
    color: var(--navy);
    font-size: 0.78rem;
    font-weight: 600;
    padding: 0.35rem 0.6rem;
    border-radius: 5px;
    cursor: pointer;
