  .toggle-pw:hover { background: #e6edf5; }

  .error-msg {
    display: none;
    color: var(--error);
    font-size: 0.82rem;
    margin-top: 0.35rem;
    font-weight: 500;
  }
  .error-msg.visible { display: flex; align-items: flex-start; gap: 0.3rem; }
  .error-msg::before { content: "⚠"; font-size: 0.8rem; line-height: 1.4; }

  .checkbox-wrap {
    display: flex;
    align-items: flex-start;
    gap: 0.6rem;
    grid-column: 1 / -1;
